                "doc.baselines.coil_name": "Bobines (Masselotte)",
                "doc.baselines.stroke_25": "2,5 mm (Court)",
                "doc.baselines.stroke_30": "3,0 mm (Court-Moyen)",
                "doc.baselines.stroke_35": "3,5 mm (Moyen)",
